use crate::aap::caps::{http_client, state_read};

struct Node;

/// Percent-encode a query component (RFC 3986 unreserved characters pass through).
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push_str(&format!("%{:02X}", b));
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Enrichment call, granted via aap:caps/http-client@0.1.0.
        // RunInfo carries no `text` field, so the input's only textual
        // field (`date`) is used as the query value. The response is
        // discarded so the node's output is unchanged. A transport
        // failure comes back as a value via `fetch` and is ignored; an
        // out-of-allowlist request traps at the boundary, as specified.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&enrich_url);

        // Subscription list from the read-only "subscriptions" store.
        // Assumed layout: key "urls" holds one URL per line. A missing
        // key yields an empty list.
        let urls: Vec<String> = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
